  def check_concrete_output(material_coordination_result: Factory_Material_Continuity_Coordinator.MaterialCoordinationResult => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val material_coordination_resultValue: Factory_Material_Continuity_Coordinator.MaterialCoordinationResult = get_material_coordination_result().get
    if(!material_coordination_result(material_coordination_resultValue)) {
